set +e
# gnsslog (generated by gnss-20261114/pl/make_guests.py; see the blocks there for what and why)
fsck.hfsplus -f -n /dev/vda | tail -2
mount -t hfsplus -o ro,force /dev/vda /work/root || exit 1
python3 - <<'GUEST'
# read-only: tails of the GNSS engine log and the bridge log into the VM log (GNSSFIX4X_LOG lines), file list of the config dir
import os
R='/work/root'
for p,n in (('/private/var/db/n2gnss/n2mnld.log.1',60),('/private/var/db/n2gnss/n2mnld.log',400),('/private/var/db/nord2-locbridge.log',80)):
    if os.path.exists(R+p):
        L=open(R+p,'rb').read().decode('utf-8','replace').splitlines()
        print('GNSSFIX4X_LOG ==', p, len(L), 'lines; last', min(n,len(L)))
        for l in L[-n:]: print('GNSSFIX4X_LOG', l[:300])
    else: print('GNSSFIX4X_LOG ==', p, 'absent')
d='/private/var/db/n2gnss'
if os.path.isdir(R+d): print('GNSSFIX4X_LOG files', sorted((n, os.path.getsize(R+d+'/'+n)) for n in os.listdir(R+d)))
GUEST
echo 'GNSSLOG_DONE'
sync
umount /work/root
echo INSTALL_DONE
